var nOL={};nOL.bookPrompt='Find a mapped book';nOL.bounds=new google.maps.LatLngBounds();nOL.clickingZooms=true;nOL.clickListener;nOL.fb_session;nOL.friendIds=[];nOL.friends;nOL.geocoder=new google.maps.Geocoder();nOL.host;nOL.locations;nOL.map;nOL.openWindow;nOL.pins={};nOL.placePrompt='Find a place & map a book to it';nOL.r;nOL.showingAllPins=true;nOL.zoomer=new google.maps.MaxZoomService();nOL.init=function(selectedLocationId){var myOptions={backgroundColor:'white',draggableCursor:'default',mapTypeId:google.maps.MapTypeId.HYBRID,minZoom:2};map=new google.maps.Map($('#map-canvas')[0],myOptions);nOL.getLocations(selectedLocationId);$('#book-input')[0].value=nOL.bookPrompt;$('#place-input')[0].value=nOL.placePrompt;$('#book-input').blur(function(){if($(this).attr('value')==''){$(this).attr('value',nOL.bookPrompt);nOL.showAllPins();}
$(this).css('color','#777');nOL.listenForShortcuts();});$('#book-input').focus(function(){if($(this).attr('value')==nOL.bookPrompt)
$(this).attr('value','');$(this).css('color','black');nOL.dontListenForShortcuts();});$('#book-input').keyup(function(){nOL.hidePins();nOL.showPins($('#book-input')[0].value);});$('#mode-button').click(nOL.toggleMapMode);$('#pin-display-button').click(nOL.togglePinDisplay);$('#place-input').blur(function(){$(this).attr('value',nOL.placePrompt);$(this).css('color','#777');nOL.listenForShortcuts();});$('#place-input').focus(function(){$(this).attr('value','');$(this).css('color','black');nOL.dontListenForShortcuts();});$('#place-input').keypress(function(e){if((e.keyCode||e.which)==13)nOL.codePlace($(this).val());});nOL.listenForShortcuts();applesearch.init();}
nOL.initFacebookSession=function(session){nOL.fb_session=session;$.cookie('fb_id',nOL.fb_session.userID);nOL.labelFacebookButton('Log Out\u00a0','Log out of Facebook');nOL.setPinDisplayPrompt();nOL.getFriends();}
nOL.checkOrientation=function(){var portrait=false;if(window.orientation!=null)
portrait=Math.abs(orientation)!=90;return portrait;}
nOL.getFacebookName=function(location){if(location.user_name==undefined){FB.api('/'+location.user_id,function(response){location.user_name=response.name;});}}
nOL.getFriendIds=function(){for(var i=0;i<nOL.friends.length;i++){nOL.friendIds[i]=nOL.friends[i].id;}}
nOL.getFriendName=function(id){if(id==nOL.fb_session.userID)
return'You';for(var i=0;i<nOL.friends.length;i++){if(nOL.friends[i].id==id)
return nOL.friends[i].name;}}
nOL.getFriends=function(){FB.api('/me/friends',function(response){nOL.friends=response.data;nOL.setLocationUserNames();nOL.getFriendIds();});}
nOL.labelFacebookButton=function(value,title){$('#login-button')[0].value=value;$('#login-button')[0].title=title;}
nOL.updateFacebookLikeButton=function(path){var iframe=$('#fb-like')[0];iframe.src=iframe.src.replace(/href=.+/,'href='+host+path);}
nOL.listenFor=function(event,args){if(nOL.clickListener!=undefined)google.maps.event.removeListener(nOL.clickListener);nOL.clickListener=google.maps.event.addListener(map,event,function(e){eval(args)});}
nOL.listenForLogin=function(){$('#login-button').click(function(){nOL.toggleLogin();});}
nOL.dontListenForShortcuts=function(){shortcut.remove('l');shortcut.remove('m');shortcut.remove('s');}
nOL.listenForShortcuts=function(){shortcut.add('l',nOL.toggleLogin);shortcut.add('m',nOL.toggleMapMode);shortcut.add('s',nOL.togglePinDisplay);}
nOL.loggedIn=function(){return!!$.cookie('fb_id');}
nOL.logIn=function(){FB.login(function(response){if(response.authResponse){nOL.initFacebookSession(response.authResponse);window.location.reload();}});}
nOL.logOut=function(){FB.logout(function(response){nOL.labelFacebookButton('Log In \u00a0 ','Log into Facebook');$.cookie('fb_id',null)
window.location.reload();nOL.listenForLogin();});}
nOL.toggleLogin=function(){nOL.loggedIn()?nOL.logOut():nOL.logIn();}
nOL.promptForTag=function(id,tags){var value=prompt('Enter some descriptive words. These will be linked to a Google search.',tags);if(value)nOL.tagPin(id,value);}
nOL.promptForNotes=function(id,notes){var value=prompt('Add any comments you would like readers to know.',notes);if(value)nOL.annotatePin(id,value);}
nOL.promptForBook=function(gLatLng,place,address){var keywords=prompt('Add a novel to the map. Our only requirement: that it be evocative of the place.\n\nEnter keywords describing the book: title, author, etc.',null);if(keywords)nOL.findBook(gLatLng,place||'',address,keywords);}
nOL.listenForDoubleClick=function(){nOL.updateFacebookLikeButton('')
nOL.clickingZooms=!nOL.clickingZooms;nOL.toggleMapMode();if(history.pushState)
history.pushState(null,'','/');}
nOL.toggleMapMode=function(){nOL.clickingZooms=!nOL.clickingZooms;if(nOL.clickingZooms){if(nOL.clickListener!=undefined)google.maps.event.removeListener(nOL.clickListener);$('#mode-button')[0].title='Double-click map to zoom. Click to toggle';$('#mode-button')[0].value='Mode: Zoom';map.setOptions({draggableCursor:'default',disableDoubleClickZoom:false});}else{nOL.listenFor('dblclick','nOL.promptForBook(e.latLng)');$('#mode-button')[0].title='Double-click map to add pins. Click to toggle';$('#mode-button')[0].value='Mode: Add Pins';map.setOptions({draggableCursor:'crosshair',disableDoubleClickZoom:true});}}
nOL.setPinDisplayPrompt=function(){$('#pin-display-button')[0].title=nOL.loggedIn()?"Click to show only friends' pins":'Click to show only my pins';$('#pin-display-button')[0].value=nOL.loggedIn()?"Show Friends'":'Show My Pins';}
nOL.togglePinDisplay=function(){nOL.showingAllPins=!nOL.showingAllPins;if(nOL.showingAllPins){nOL.showAllPins();nOL.setPinDisplayPrompt();}else{nOL.hideStrangersPins();$('#pin-display-button')[0].title='Click to show all pins';$('#pin-display-button')[0].value='Show All Pins';}}
nOL.addPin=function(location){var latLng=nOL.toLatLng(location.lat_lng);var pin=new google.maps.Marker({map:map,draggable:location.writable,animation:google.maps.Animation.DROP,position:latLng});nOL.bounds.extend(latLng);nOL.pins[location._id]=pin;google.maps.event.addListener(pin,'click',function(){var path='/locations/'+location._id;if(history.pushState)
history.pushState(null,location.title,path);nOL.updateFacebookLikeButton(path);nOL.openBalloon(location);});google.maps.event.addListener(pin,'dragend',function(){if(confirm('Move this pin?'))
nOL.movePin(location._id,pin.getPosition());else
pin.setPosition(latLng);});}
nOL.addPins=function(selectedLocationId){for(var i=0;i<locations.length;i++){nOL.addPin(locations[i]);if(locations[i].writable&&locations[i].user_id==undefined){nOL.claimPin(locations[i]._id);}
if(selectedLocationId&&locations[i]._id==selectedLocationId){nOL.openBalloon(locations[i]);nOL.zoomIn(nOL.toLatLng(locations[i].lat_lng));}}
map.fitBounds(nOL.bounds);}
nOL.shouldAddPin=function(googleResults){var types=googleResults.types;var typesToPin=['establishment','point_of_interest','street_address']
for(var i=0;i<typesToPin.length;i++){if($.inArray(typesToPin[i],types))return true;}
return false;}
nOL.hidePin=function(id){nOL.pins[id].setMap(null);}
nOL.hidePins=function(){for(var i=0;i<locations.length;i++){nOL.hidePin(locations[i]._id);}}
nOL.hideStrangersPins=function(){for(var i=0;i<locations.length;i++){var pinId=locations[i]._id;var pinUserId=locations[i].user_id;if(!locations[i].writable&&(!nOL.loggedIn()||(nOL.loggedIn()&&$.inArray(pinUserId,nOL.friendIds)==-1)))
nOL.hidePin(pinId);else
nOL.pins[pinId].setMap(map);}}
nOL.setLocationUserNames=function(){for(var i=0;i<locations.length;i++){if(locations[i].user_name==undefined&&locations[i].user_id)
locations[i].user_name=nOL.getFriendName(locations[i].user_id)||nOL.getFacebookName(locations[i]);}}
nOL.showAllPins=function(){for(var i=0;i<locations.length;i++){nOL.pins[locations[i]._id].setMap(map);}}
nOL.showPins=function(keyword){for(var i=0;i<locations.length;i++){if(keyword!=''&&locations[i].terms.toLowerCase().indexOf(keyword.toLowerCase())>0){nOL.pins[locations[i]._id].setMap(map);}else if(keyword==''){nOL.showAllPins();}}}
nOL.codePlace=function(input){nOL.geocoder.geocode({'address':input},function(results,status){if(status==google.maps.GeocoderStatus.OK){r=results[0];nOL.zoomIn(r.geometry.location);if(nOL.shouldAddPin(r))nOL.promptForBook(r.geometry.location,input,r.formatted_address);}else
alert("Couldn't geocode! The error was "+status);});}
nOL.zoomIn=function(gLatLng){nOL.zoomer.getMaxZoomAtLatLng(gLatLng,function(response){map.setCenter(gLatLng);if(response.status!=google.maps.MaxZoomStatus.OK){alert("Couldn't zoom!");map.setZoom(8);return;}else
map.setZoom(map.getZoom()==response.zoom-5?response.zoom-3:response.zoom-5);});}
nOL.zoomOut=function(){map.setZoom(nOL.checkOrientation()?3:2);}
nOL.openBalloon=function(location){if(nOL.openWindow!=undefined)nOL.openWindow.close();html='<div class="map-balloon">';if(location.user_id==null&&location.user_token==null)html+='<input onClick="nOL.claimPin(\''+location._id+'\')" type="button" value="Claim" title="Claim this pin"/>';if(location.writable)html+='<input onClick="nOL.deletePin(\''+location._id+'\')" type="button" value="Delete" title="Delete this pin"/><input onClick="nOL.promptForTag(\''+location._id+'\', \''+location.tags+'\')" type="button" value="Tag" title="Tag pin"/><input onClick="nOL.promptForNotes(\''+location._id+'\', \''+(location.notes||'')+'\')" type="button" value="Annotate" title="Annotate pin"/>';html+='<input onClick="nOL.zoomIn(nOL.toLatLng(['+location.lat_lng+']))" type="button" value="Zoom" title="Zoom to pin"/>'
if(location.image_url)
html+='<h1><a href="'+location.url+'" target="_blank"><img src="'+location.image_url+'" alt="Cover of '+location.title+'" class="thumbnail" height='+location.image_height+' width='+location.image_width+'/>'+location.title+'</a></h1>';else
html+='<h1><a href="'+location.url+'" target="_blank">'+location.title+'</a></h1>';html+='<h2>by <a href="http://en.wikipedia.org/wiki/'+encodeURI(location.author)+'" target="_blank">'+location.author+'</a></h2><h2>'+location.address+'</h2>'
if(location.review)
html+='<p class="clear">'+location.review+'</p>';else
html+='<p><em>No reviews found.</em></p>';if(location.notes)html+='<h3>Reader Notes</h3><p>'+location.notes+'</p>';if(nOL.fb_session&&location.user_id){html+='Added by <a href="http://www.facebook.com/profile.php?id='+location.user_id+'" id="'+location.user_id+'" target="_blank">'+(location.user_name||'You')+'</a> on '+location.added_at+'<br/>';}else{html+='Added on '+location.added_at+'<br/>';}
if(location.user_id)
html+='<input onClick="nOL.hidePins();nOL.showPins(\''+location.user_id+'\');nOL.zoomOut()" type="button" value="Other Pins" title="Show other pins added by the same reader"/><span class="bullet">|</span>';html+='<input onClick="nOL.hidePins();nOL.showPins(\''+location.author+'\');nOL.zoomOut()" type="button" value="Other Books" title="Show other books by the same author"/><span class="bullet">|</span><input onClick="nOL.hidePins();nOL.showPins(\''+location.title_for_regex+'\');nOL.zoomOut()" type="button" value="Other Locations" title="Show other locations for this book"/>';if(location.tags)html+='Tags: <a href="http://www.google.com/search?q='+encodeURI(location.tags)+'" target="_blank">'+location.tags+'</a>'
html+='</p></div>';nOL.openWindow=new google.maps.InfoWindow({content:html});nOL.openWindow.open(map,nOL.pins[location._id]);google.maps.event.addListener(nOL.openWindow,'closeclick',function(){nOL.listenForDoubleClick()});nOL.listenFor('click','nOL.openWindow.close(); nOL.listenForDoubleClick()');}
nOL.annotatePin=function(id,notes){$.ajax({type:'PUT',url:'/locations/'+id,data:{'location[notes]':notes}});}
nOL.claimPin=function(id){$.ajax({type:'PUT',url:'/locations/'+id,data:{'caller':'claim','location[user_id]':nOL.fb_session&&nOL.fb_session.userID||null,'location[user_token]':$.cookie('user_token')}});}
nOL.createPin=function(latLng,place,address,keywords){$.post('/locations',{'location[address]':(address||''),'location[book_keywords]':keywords,'location[latLng]':nOL.toLatLng(latLng).toUrlValue(),'location[tags]':place,'location[user_id]':nOL.fb_session&&nOL.fb_session.userID||null,'location[user_token]':$.cookie('user_token')});}
nOL.deletePin=function(id){if(confirm('Are you sure? This action cannot be undone.')){$.ajax({type:'DELETE',url:'/locations/'+id})}}
nOL.findBook=function(gLatLng,place,address,keywords){$.get('/locations/new',{'location[address]':(address||''),'location[tags]':place,'location[book_keywords]':keywords,'location[latLng]':gLatLng.toUrlValue()});}
nOL.getLocations=function(selectedLocationId){$.get('/locations.json',{'t':new Date().getTime(),'user_token':$.cookie('user_token')},function(data){locations=data;nOL.addPins(selectedLocationId);});}
nOL.movePin=function(id,gLatLng){$.ajax({type:'PUT',url:'/locations/'+id,data:{'location[latLng]':gLatLng.toUrlValue()}});}
nOL.tagPin=function(id,tags){$.ajax({type:'PUT',url:'/locations/'+id,data:{'location[tags]':tags}});}
nOL.toLatLng=function(latLng){return new google.maps.LatLng(latLng[0],latLng[1]);}
var applesearch;if(!applesearch)applesearch={};applesearch.init=function()
{if(navigator.userAgent.toLowerCase().indexOf('safari')<0&&document.getElementById)
{this.clearBtn=false;}}
applesearch.onChange=function(fldID,btnID)
{var fld=document.getElementById(fldID);var btn=document.getElementById(btnID);if(fld.value.length>0&&!this.clearBtn)
{btn.style.background="white url('/images/srch_r_f2.gif') no-repeat top left";btn.fldID=fldID;btn.onclick=this.clearBtnClick;this.clearBtn=true;}else if(fld.value.length==0&&this.clearBtn)
{btn.style.background="white url('/images/srch_r.gif') no-repeat top left";btn.onclick=null;this.clearBtn=false;}}
applesearch.clearFld=function(fldID,btnID)
{var fld=document.getElementById(fldID);fld.value='';this.onChange(fldID,btnID);if(fldID=='book-input'){nOL.hidePins();nOL.showPins($('#book-input')[0].value);}}
applesearch.clearBtnClick=function()
{applesearch.clearFld(this.fldID,this.id);}
jQuery.cookie=function(name,value,options){if(typeof value!='undefined'){options=options||{};if(value===null){value='';options.expires=-1;}
var expires='';if(options.expires&&(typeof options.expires=='number'||options.expires.toUTCString)){var date;if(typeof options.expires=='number'){date=new Date();date.setTime(date.getTime()+(options.expires*24*60*60*1000));}else{date=options.expires;}
expires='; expires='+date.toUTCString();}
var path=options.path?'; path='+(options.path):'';var domain=options.domain?'; domain='+(options.domain):'';var secure=options.secure?'; secure':'';document.cookie=[name,'=',encodeURIComponent(value),expires,path,domain,secure].join('');}else{var cookieValue=null;if(document.cookie&&document.cookie!=''){var cookies=document.cookie.split(';');for(var i=0;i<cookies.length;i++){var cookie=jQuery.trim(cookies[i]);if(cookie.substring(0,name.length+1)==(name+'=')){cookieValue=decodeURIComponent(cookie.substring(name.length+1));break;}}}
return cookieValue;}};